-- Official Cat Parts Store category references: attachments and structures.
-- Reference-only records; no sales price, stock, or fitment is inferred.
on conflict (part_number) do update set
 name=excluded.name,description=excluded.description,technical_group=excluded.technical_group,
 source_name=excluded.source_name,source_url=excluded.source_url,source_note=excluded.source_note,
 verification_status='REFERENCE',image_url=excluded.image_url,specifications=excluded.specifications,
 compatible_models=excluded.compatible_models,updated_at=now();
